package coralnpu

import chisel3._
import chisel3.util._
import common.Fp32

// Read port interface
class FRegReadPort extends Bundle {
  val valid = Input(Bool())
  val addr  = Input(UInt(5.W))
  val data  = Output(new Fp32)
}

// Write port interface
class FRegWritePort extends Bundle {
  val valid = Input(Bool())
  val addr  = Input(UInt(5.W))
  val data  = Input(new Fp32)
}

// Floating-point register file with a scoreboard for in-flight tracking.
//
// Parameters:
//   p           - top-level design parameters
//   nReadPorts  - number of combinational read ports
//   nWritePorts - number of synchronous write ports
//
// Scoreboard semantics:
//   - scoreboard_set (input): ORed into the scoreboard on the next clock edge
//   - Writing a register clears the corresponding scoreboard bit
//   - Set and clear can happen simultaneously; the write (clear) takes priority
//     over the set for the same bit within the same cycle, producing the
//     combined next value = (current | set) & ~written_mask
//
// Exception:
//   - exception is asserted (combinationally) when two valid write ports
//     target the same register address in the same cycle.
class FRegfile(p: Parameters, nReadPorts: Int, nWritePorts: Int) extends Module {
  val io = IO(new Bundle {
    val scoreboard     = Output(UInt(32.W))
