    val clk      = Input(Clock())
    val rst      = Input(Bool())
    val valid_i  = Input(Bool())
    val optype_i = Input(UInt(5.W))
    val waddr_i  = Input(UInt(5.W))
    val ina_i    = Input(UInt(32.W))
    val inb_i    = Input(UInt(32.W))
    val inc_i    = Input(UInt(32.W))
