       |  input  logic        valid_i,
       |  input  logic [4:0]  optype_i,
       |  input  logic [4:0]  waddr_i,
       |  input  logic [31:0] ina_i,
       |  input  logic [31:0] inb_i,
       |  input  logic [31:0] inc_i,
