15	package coralnpu.rvv
16	
17	import chisel3._
18	import chisel3.util._
19	
20	// funct3 values for RVV
21	object RvvFunct3 {
22	  val OPIVV = 0.U(3.W)  // vector-vector integer
23	  val OPFVV = 1.U(3.W)  // vector-vector float
24	  val OPMVV = 2.U(3.W)  // vector-vector mask/multiply
25	  val OPIVI = 3.U(3.W)  // vector-immediate
26	  val OPIVX = 4.U(3.W)  // vector-scalar integer
27	  val OPFVX = 5.U(3.W)  // vector-scalar float
28	  val OPMVX = 6.U(3.W)  // vector-scalar mask/multiply
29	  val OPCFG = 7.U(3.W)  // vector configuration (setvl*)
30	}
31	
32	// Decode a 32-bit RISC-V instruction as an RVV instruction.
33	// Returns Valid(decoded) where valid=true iff it is an RVV instruction.
34	object RvvS1DecodeInstruction {
35	  def apply(inst: UInt): ValidIO[RvvS1DecodedInstruction] = {
36	    val out = Wire(Valid(new RvvS1DecodedInstruction()))
37	
38	    // RVV opcode = 0x57 (VECTOR)
39	    val opcode  = inst(6, 0)
40	    val isRvv   = opcode === 0x57.U
41	
42	    val vd      = inst(11, 7)
43	    val funct3  = inst(14, 12)
44	    val vs1_rs1 = inst(19, 15)
45	    val vs2     = inst(24, 20)
46	    val vm      = inst(25)           // 0=masked, 1=unmasked
47	    val funct6  = inst(31, 26)
48	
49	    // SETVL* detection: funct3 = OPCFG(7)
50	    val isSetVl = isRvv && (funct3 === RvvFunct3.OPCFG)
51	
52	    // Default all fields
53	    out.valid            := false.B
54	    out.bits.op          := RvvAluOp.VADD
55	    out.bits.vd          := vd
56	    out.bits.vs1         := vs1_rs1
57	    out.bits.vs2         := vs2
58	    out.bits.vm          := vm
59	    out.bits.imm         := vs1_rs1.asSInt
60	    out.bits.rs1         := vs1_rs1
61	    out.bits.funct3      := funct3
62	    out.bits.isMemory    := false.B
63	    out.bits.isLoad      := false.B
64	    out.bits.isSetVl     := false.B
65	
66	    when (isRvv) {
67	      out.valid       := true.B
68	      out.bits.isSetVl := isSetVl
69	
70	      when (isSetVl) {
71	        // VSETVL:   inst[31:30] = 10
72	        // VSETIVLI: inst[31:30] = 11
73	        // VSETVLI:  inst[31]    = 0
74	        when (inst(31, 30) === "b10".U) {
75	          out.bits.op := RvvAluOp.VSETVL
76	        } .elsewhen (inst(31, 30) === "b11".U) {
77	          out.bits.op := RvvAluOp.VSETIVLI
78	        } .otherwise {
79	          out.bits.op := RvvAluOp.VSETVLI
80	        }
81	      } .otherwise {
82	        // Main decode by funct6
83	        switch (funct6) {
84	          is (0x00.U) { out.bits.op := RvvAluOp.VADD }
85	          is (0x02.U) { out.bits.op := RvvAluOp.VSUB }
86	          is (0x03.U) { out.bits.op := RvvAluOp.VRSUB }
87	          is (0x04.U) { out.bits.op := RvvAluOp.VMINU }
88	          is (0x05.U) { out.bits.op := RvvAluOp.VMIN }
89	          is (0x06.U) { out.bits.op := RvvAluOp.VMAXU }
90	          is (0x07.U) { out.bits.op := RvvAluOp.VMAX }
91	          is (0x09.U) { out.bits.op := RvvAluOp.VAND }
92	          is (0x0a.U) { out.bits.op := RvvAluOp.VOR }
93	          is (0x0b.U) { out.bits.op := RvvAluOp.VXOR }
94	          is (0x0c.U) { out.bits.op := RvvAluOp.VRGATHER }
95	          is (0x0d.U) { out.bits.op := RvvAluOp.VSLIDEUP }
96	          is (0x0e.U) {
97	            // funct6=0x0e: VRGATHEREI16 when funct3=OPIVV(0), else VSLIDEUP
98	            when (funct3 === RvvFunct3.OPIVV) {
99	              out.bits.op := RvvAluOp.VRGATHEREI16
100	            } .otherwise {
101	              out.bits.op := RvvAluOp.VSLIDEUP
102	            }
103	          }
104	          is (0x0f.U) { out.bits.op := RvvAluOp.VSLIDEDOWN }
105	          is (0x10.U) { out.bits.op := RvvAluOp.VADC }
106	          is (0x11.U) { out.bits.op := RvvAluOp.VMADC }
107	          is (0x12.U) { out.bits.op := RvvAluOp.VSBC }
108	          is (0x13.U) { out.bits.op := RvvAluOp.VMSBC }
109	          is (0x17.U) {
110	            // funct6=0x17: VMERGE when masked (vm=0), VMV when unmasked (vm=1)
111	            when (vm) {
112	              out.bits.op := RvvAluOp.VMV
113	            } .otherwise {
114	              out.bits.op := RvvAluOp.VMERGE
115	            }
116	          }
117	          is (0x18.U) { out.bits.op := RvvAluOp.VMSEQ }
118	          is (0x19.U) { out.bits.op := RvvAluOp.VMSNE }
119	          is (0x1a.U) { out.bits.op := RvvAluOp.VMSLTU }
120	          is (0x1b.U) { out.bits.op := RvvAluOp.VMSLT }
121	          is (0x1c.U) { out.bits.op := RvvAluOp.VMSLEU }
122	          is (0x1d.U) { out.bits.op := RvvAluOp.VMSLE }
123	          is (0x1e.U) { out.bits.op := RvvAluOp.VMSGTU }
124	          is (0x1f.U) { out.bits.op := RvvAluOp.VMSGT }
125	          is (0x20.U) { out.bits.op := RvvAluOp.VSADDU }
126	          is (0x21.U) { out.bits.op := RvvAluOp.VSADD }
127	          is (0x22.U) { out.bits.op := RvvAluOp.VSSUBU }
128	          is (0x23.U) { out.bits.op := RvvAluOp.VSSUB }
129	          is (0x25.U) { out.bits.op := RvvAluOp.VSLL }
130	          is (0x27.U) {
131	            // funct6=0x27: VSMUL (vv/vx) or VMVxR (vi, based on imm/vs1)
132	            when (funct3 === RvvFunct3.OPIVI) {
133	              // VMV1R=imm0, VMV2R=imm1, VMV4R=imm3, VMV8R=imm7
134	              switch (vs1_rs1) {
135	                is (0.U) { out.bits.op := RvvAluOp.VMV1R }
136	                is (1.U) { out.bits.op := RvvAluOp.VMV2R }
137	                is (3.U) { out.bits.op := RvvAluOp.VMV4R }
138	                is (7.U) { out.bits.op := RvvAluOp.VMV8R }
139	              }
140	            } .otherwise {
141	              out.bits.op := RvvAluOp.VSMUL
142	            }
143	          }
144	          is (0x28.U) { out.bits.op := RvvAluOp.VSRL }
145	          is (0x29.U) { out.bits.op := RvvAluOp.VSRA }
146	          is (0x2a.U) { out.bits.op := RvvAluOp.VSSRL }
147	          is (0x2b.U) { out.bits.op := RvvAluOp.VSSRA }
148	          is (0x2c.U) { out.bits.op := RvvAluOp.VNSRL }
149	          is (0x2d.U) { out.bits.op := RvvAluOp.VNSRA }
150	          is (0x2e.U) { out.bits.op := RvvAluOp.VNCLIPU }
151	          is (0x2f.U) { out.bits.op := RvvAluOp.VNCLIP }
152	        }
153	      }
154	    }
155	
156	    out
157	  }
158	}
159	
160	// Decode a compressed RVV instruction (stored as full 32-bit encoding).
161	object RvvS1DecodeCompressedInstruction {
162	  def apply(c: RvvCompressedInstruction): ValidIO[RvvS1DecodedInstruction] = {
163	    RvvS1DecodeInstruction(c.inst)
164	  }
165	}
